// 通用 split 函数
vector<string> split(const string& str, const string& delimiter) {
    vector<string> result;
    size_t start = 0;
    size_t end = str.find(delimiter);
    while (end != string::npos) {
        result.push_back(str.substr(start, end - start));
        start = end + delimiter.length();
        end = str.find(delimiter, start);
    }
    // 添加最后一个部分
    result.push_back(str.substr(start));
    return result;
}
​
bool cmp(const string & a, const string& b) {
    if (a.size() == b.size()) {
        return a < b;
    }
    return a.size() < b.size();
}
​
int main() {
    string s;
    getline(cin, s);
    vector<string> ans = split(s, " ");
​
    // 按照长度和字典序排序
    sort(ans.begin(), ans.end(), cmp);
    if (ans[0].size() != 1) {
        cout << "";
        return 0;
    }
    // 记录出现过的字符
    set<string> strSet;
    // 记录已经访问过的字符
    map<string, bool> mp;
    int n = ans.size();
    for (int i = 0; i < n; i++) {
        strSet.insert(ans[i]);
        mp[ans[i]] = false;
    }

    string res = "";
    for (int i = n-1; i >= 0; i--) {
        string tmp = ans[i];
        // 已经访问过但是之前作为前缀不成立，所以这个字符串肯定也不成立
        if (mp[tmp]) {
            continue;
        }
        // 迭代判断
        while (tmp != "") {
            tmp.pop_back();
            // 没有指定前缀字符串
            if (strSet.count(tmp) == 0) {
                break;
            }
            // 已经访问过，之前没有得出结果，肯定不满足条件
            if (mp[tmp]) {
                break;
            }
            mp[tmp] = true;

        }
        if (tmp  == "") {
            res = ans[i];
            break;
        }
    }
    cout << res;
    return 0;
}

