const readline = require("readline");
​
const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});
​
rl.on("line", (line) => {
    let ans = line.trim().split(" ");

    // 按长度和字典序排序
    ans.sort((a, b) => a.length === b.length ? a.localeCompare(b) : a.length - b.length);
​
    if (ans[0].length !== 1) {
        console.log("");
        rl.close();
        return;
    }
​
    let strSet = new Set(ans);
    let visited = new Map();
​
    let res = "";
    for (let i = ans.length - 1; i >= 0; i--) {
        let tmp = ans[i];
        // 之前作为某个字符串的前缀访问过不成立，这次肯定也不成立
        if (visited.get(tmp)) continue;
​
        // 迭代判断
        while (tmp.length > 0) {
            tmp = tmp.slice(0, -1);
            if (!strSet.has(tmp)) break;
            if (visited.get(tmp)) break;
            visited.set(tmp, true);
        }
​
        if (tmp.length === 0) {
            res = ans[i];
            break;
        }
    }
​
    console.log(res);
    rl.close();
});
