package main
​
import (
    "bufio"
    "fmt"
    "os"
    "sort"
    "strings"
)
​
func main() {
    reader := bufio.NewReader(os.Stdin)
    s, _ := reader.ReadString('\n')
    s = strings.TrimSpace(s)
​
    words := strings.Split(s, " ")
    // 按长度和字典序排序
    sort.Slice(words, func(i, j int) bool {
        if len(words[i]) == len(words[j]) {
            return words[i] < words[j]
        }
        return len(words[i]) < len(words[j])
    })
​
    if len(words[0]) != 1 {
        fmt.Println("")
        return
    }
​
    strSet := make(map[string]bool)
    visited := make(map[string]bool)
​
    for _, word := range words {
        strSet[word] = true
        visited[word] = false
    }
​
    res := ""
    for i := len(words) - 1; i >= 0; i-- {
        tmp := words[i]
        // 之前作为某个字符串的前缀访问过不成立，这次肯定也不成立
        if visited[tmp] {
            continue
        }
​
        // 迭代判断
        for len(tmp) > 0 {
            tmp = tmp[:len(tmp)-1]
            if !strSet[tmp] {
                break
            }
            if visited[tmp] {
                break
            }
            visited[tmp] = true
        }
​
        if len(tmp) == 0 {
            res = words[i]
            break
        }
    }
​
    fmt.Println(res)
}
